import React, { useState, useEffect } from "react";
import { gsap } from "gsap";
import { MorphSVGPlugin } from "gsap/MorphSVGPlugin";

gsap.registerPlugin(MorphSVGPlugin);

// 🎬 Animation Component
const FarmerAnimation = ({ onFinish }) => {
  useEffect(() => {
    // Step 1: Farmer enters
    gsap.fromTo("#farmer", { x: -200 }, { x: 0, duration: 2, ease: "power2.out" });

    // Step 2: Water drops
    gsap.fromTo(
      "#water",
      { opacity: 0, y: -20 },
      { opacity: 1, y: 0, duration: 1, delay: 2, repeat: 3 }
    );

    // Step 3: Plant grows
    gsap.fromTo(
      "#plant",
      { scale: 0.3, transformOrigin: "center" },
      { scale: 1, duration: 2, delay: 4, ease: "elastic.out(1, 0.5)" }
    );

    // Step 4: Morph plant → form
    gsap.to("#plant", {
      delay: 6,
      duration: 2,
      morphSVG: "#formBox",
      ease: "power2.inOut",
      onComplete: () => {
        setTimeout(onFinish, 1000); // show real form after morph
      },
    });
  }, [onFinish]);

  return (
    <div className="flex items-center justify-center min-h-screen bg-green-100 relative">
      <svg width="500" height="400" viewBox="0 0 500 400">
        {/* Farmer (placeholder SVG) */}
        <circle id="farmer" cx="80" cy="250" r="40" fill="#fbbf24" />
        <rect x="60" y="290" width="40" height="80" fill="#2563eb" />

        {/* Water drops */}
        <circle id="water" cx="140" cy="280" r="6" fill="#3b82f6" opacity="0" />

        {/* Plant (morphable) */}
        <path
          id="plant"
          d="M250 300 Q245 250 250 200 Q230 190 220 170 Q235 175 250 190 Q265 175 280 170 Q270 190 250 200 Q255 250 250 300 Z"
          fill="#22c55e"
        />

        {/* Hidden Form Rectangle */}
        <rect
          id="formBox"
          x="180"
          y="150"
          width="180"
          height="120"
          rx="20"
          fill="#22c55e"
          style={{ visibility: "hidden" }}
        />
      </svg>
    </div>
  );
};

// 🎯 Main App
export default function App() {
  const [isFormVisible, setIsFormVisible] = useState(false);
  const [showAnimation, setShowAnimation] = useState(false);

  const renderHomeScreen = () => (
    <div className="flex flex-col items-center justify-center min-h-screen bg-green-700 text-white">
      <h1 className="text-4xl font-bold mb-6">TEAM IOTA Presents</h1>
      <p className="mb-4">Based on our trained ML model</p>
      <button
        className="px-6 py-3 bg-yellow-400 text-black font-semibold rounded-lg shadow-lg hover:bg-yellow-300 transition"
        onClick={() => {
          setIsFormVisible(true);
          setShowAnimation(true);
        }}
      >
        Enter Application
      </button>
    </div>
  );

  return (
    <div>
      {!isFormVisible ? (
        renderHomeScreen()
      ) : showAnimation ? (
        <FarmerAnimation onFinish={() => setShowAnimation(false)} />
      ) : (
        // 🌱 Your Real Form
        <div className="flex flex-col items-center justify-center min-h-screen bg-green-50">
          <h2 className="text-3xl font-bold mb-6 text-green-800">Soil Health & Fertilizer Recommendation</h2>
          <form className="bg-white shadow-lg rounded-lg p-6 w-96">
            <input
              type="text"
              placeholder="Soil Type"
              className="w-full mb-4 p-2 border rounded"
            />
            <input
              type="number"
              placeholder="Moisture %"
              className="w-full mb-4 p-2 border rounded"
            />
            <input
              type="number"
              placeholder="Nitrogen Level"
              className="w-full mb-4 p-2 border rounded"
            />
            <input
              type="number"
              placeholder="Phosphorus Level"
              className="w-full mb-4 p-2 border rounded"
            />
            <input
              type="number"
              placeholder="Potassium Level"
              className="w-full mb-4 p-2 border rounded"
            />
            <button className="w-full bg-green-600 text-white py-2 rounded hover:bg-green-700">
              Predict
            </button>
          </form>
        </div>
      )}
    </div>
  );
}
